def minOperations(nums):
    # Build all palindromes with up to 10 digits, in increasing order, split by parity
    evens, odds = [], []
    for length in range(1, 11):
        half = (length + 1) // 2
        # A palindrome is determined by its first half
        for h in range(10 ** (half - 1), 10 ** half):
            s = str(h)
            if length % 2 == 0:
                full = s + s[::-1]
            else:
                # For odd length the middle digit is not repeated
                full = s + s[:-1][::-1]
            v = int(full)
            if v % 2 == 0:
                evens.append(v)
            else:
                odds.append(v)

    total = 0
    for x in nums:
        # Only palindromes with the same parity as x are reachable with steps of 2
        arr = evens if x % 2 == 0 else odds
        # Binary search for the first palindrome >= x
        lo, hi = 0, len(arr)
        while lo < hi:
            mid = (lo + hi) // 2
            if arr[mid] < x:
                lo = mid + 1
            else:
                hi = mid
        # Distance to the next palindrome above (if any) and the one below (if any)
        best = float('inf')
        if lo < len(arr):
            best = arr[lo] - x
        if lo > 0 and x - arr[lo - 1] < best:
            best = x - arr[lo - 1]
        # Each operation moves by exactly 2
        total += best // 2
    return total
